void require(bool condition,const char *message){if(!condition)throw std::runtime_error(message);}
using Pixel=std::array<int,4>;
std::vector<Pixel> read_png16(const QString &path,int expected_components,int expected_bits=16){
 QFile file(path);require(file.open(QIODevice::ReadOnly),"Derived PNG missing");const auto header=file.read(26);require(header.size()==26&&int(static_cast<unsigned char>(header[24]))==expected_bits,"Derived PNG lost native 16-bit precision");const int type=static_cast<unsigned char>(header[25]);require(type==(expected_components==1?0:expected_components==4?6:2),"Derived output channel layout changed");
 if(expected_bits==8){require(!QImage(path).isNull(),"Cannot decode PNG8 default color");return {};}
 using Buffer=std::unique_ptr<blender::ImBuf,decltype(&blender::IMB_freeImBuf)>;Buffer image(blender::IMB_load_image_from_filepath(path.toUtf8().constData(),blender::ImBufFlags::FloatData|blender::ImBufFlags::NoColorspaceConvert|blender::ImBufFlags::AlphaChannelPacked),blender::IMB_freeImBuf);require(image&&image->float_data(),"Native 16-bit PNG decode failed");std::vector<Pixel> result(std::size_t(image->x)*image->y);const auto *data=image->float_data();for(std::size_t i=0;i<result.size();++i){for(int c=0;c<3;++c)result[i][c]=int(std::lround(data[i*image->channels+(image->channels>=3?c:0)]*65535));result[i][3]=image->channels==4?int(std::lround(data[i*4+3]*65535)):65535;}return result;
}
