QJsonObject verify_derived_export_files(const QString &directory){
 const QDir converted(QDir(directory).filePath("converted")),direct(QDir(directory).filePath("direct"));const auto one=[](const QDir &folder,const QString &suffix){const auto files=folder.entryList({"*_"+suffix+".png"},QDir::Files);require(files.size()==1,"Expected one map for the selected Texture Set");return folder.filePath(files.front());};require(converted.entryList({"*.png"},QDir::Files).size()==5,"Converted GUI preset must export five maps");require(converted.entryList({"*normal*"},QDir::Files).isEmpty()&&direct.entryList({"*normal*"},QDir::Files).isEmpty(),"GUI export wrote a normal map");const auto rough=read_png16(one(direct,"roughness"),1),gloss=read_png16(one(converted,"glossiness"),1),bump=read_png16(one(direct,"bump"),1);require(rough.size()==512*512&&gloss.size()==rough.size()&&bump.size()==rough.size(),"Converted output must be 512 square");int minimum=65535,maximum=0;for(std::size_t p=0;p<rough.size();++p){require(rough[p][0]+gloss[p][0]==65535,"GUI roughness/glossiness sum is not exactly 65535");minimum=std::min(minimum,rough[p][0]);maximum=std::max(maximum,rough[p][0]);}require(minimum<maximum,"GUI fixture must vary roughness");read_png16(one(converted,"diffuse"),4,8);read_png16(one(converted,"specular"),3);read_png16(one(converted,"bump"),1);const auto emissive=read_png16(one(converted,"emissive"),3);for(const auto &pixel:emissive)require(pixel[0]==0&&pixel[1]==0&&pixel[2]==0,"Absent emissive input must be black");return {{"pixels",int(rough.size())},{"png_bits",16},{"converted_files",5},{"direct_files",direct.entryList({"*.png"},QDir::Files).size()},{"roughness_min",minimum},{"roughness_max",maximum},{"roughness_glossiness_sum",65535},{"bump_one_channel",true},{"normal_maps",0},{"diffuse_rgba",true},{"emissive_neutral_black",true},{"native_imbuf_decoder",true}};
}
